let navData=[],navGraph=null,navRoute=null,navGPS=null,navWatch=null,navFrame=0,navMarker=null,navDot=null,navSteps=[],navElapsed=0,navLastTime=0,navRunning=false,navHeading=0;
const navPanel=document.querySelector('#navigation-panel'),navStatus=document.querySelector('#navigation-status');
const navReady=fetch('campus.json').then(r=>{if(!r.ok)throw Error('Path data could not load.');return r.json()}).then(data=>{navData=data;navGraph=CampusRouting.build(data)});
const navLocationStatus=document.querySelector('#location-status');
function selectGPS(on){for(const input of [fields.from.room,fields.from.building,fields.from.floor])input.disabled=on;document.querySelector('#use-building').hidden=!on;document.querySelector('#use-location').textContent=on?'⌖ Refresh my location':'⌖ Use my current location'}
function requestLocation(){navGPS=null;selectGPS(false);if(!navigator.geolocation){navLocationStatus.textContent='Location is unavailable in this browser. Choose a starting building.';return}navLocationStatus.textContent='Requesting your device location…';navigator.geolocation.getCurrentPosition(pos=>{if(pos.coords.accuracy>50){navLocationStatus.textContent='Location accuracy is ±'+Math.round(pos.coords.accuracy)+' m. Move outdoors and retry, or select your starting building.';return}navGPS={point:[pos.coords.longitude,pos.coords.latitude],accuracy:pos.coords.accuracy,time:Date.now()};selectGPS(true);navLocationStatus.textContent='Current location selected · accuracy ±'+Math.round(navGPS.accuracy)+' m. Used only in this browser.';clearResult()},err=>{navLocationStatus.textContent=err.code===1?'Location permission was declined. Choose a starting building instead.':'Could not get an accurate location. Try outdoors or choose a building.'},{enableHighAccuracy:true,timeout:15000,maximumAge:10000})}
document.querySelector('#use-location').onclick=requestLocation;document.querySelector('#use-building').onclick=()=>{navGPS=null;selectGPS(false);navLocationStatus.textContent='Choose your starting building.';stopLive()};document.querySelector('#swap').addEventListener('click',()=>{if(navGPS){navGPS=null;selectGPS(false);navLocationStatus.textContent='Location cleared. Choose a starting building after swapping.'}});
const universityHallApproach={point:[-112.8609983,49.6781811],name:'University Hall — reported west approach',source:'Reported by Deep near the Library/Arts connection; approximate approach location, not a surveyed door.',accessibility:'unknown'};
const studentsUnionRearApproach={point:[-112.8638217,49.6780503],name:'Students’ Union — reported rear approach',source:'Rear entrance approach reported by Deep in an annotated map screenshot; existing mapped footway 256672147.',accessibility:'unknown'};
function navEndpoint(id){if(String(id)==='118467730'){const f=navData.find(f=>String(f.id)===String(id));return {alternatives:[{point:studentsUnionRearApproach.point,maxSnap:3,reportedApproach:true,approachName:studentsUnionRearApproach.name},{ring:f.points,maxSnap:70}]}}if(String(id)==='118457919')return {point:universityHallApproach.point,maxSnap:3,reportedApproach:true,approachName:universityHallApproach.name};const f=navData.find(f=>String(f.id)===String(id));if(!f)throw Error('Building geometry is unavailable. Choose another building.');return {ring:f.points,maxSnap:70}}
function stopLive(){if(navWatch!==null)navigator.geolocation.clearWatch(navWatch);navWatch=null}
function stopAnimation(){cancelAnimationFrame(navFrame);navRunning=false;}
function clearNavigation(){stopAnimation();stopLive();navMarker?.remove();navMarker=null;document.querySelector('#nav-2d')?.remove();if(threeReady&&campus3D.getSource('navigation-route'))campus3D.getSource('navigation-route').setData(featureCollection([]));navRoute=null;navPanel.hidden=true;document.body.classList.remove('navigating')}
function distanceText(d){return d>=1000?(d/1000).toFixed(1)+' km':Math.round(d)+' m'}
function routeStepList(route){const list=[{index:0,distance:0,text:'Start on the highlighted pedestrian path.'}];let last=0;for(let i=1;i<route.coords.length-1;i++){const before=CampusRouting.bearing(route.coords[i-1],route.coords[i]),after=CampusRouting.bearing(route.coords[i],route.coords[i+1]),angle=((after-before+540)%360)-180;if(Math.abs(angle)>=40&&route.cumulative[i]-last>=8){list.push({index:i,distance:route.cumulative[i],text:'After '+distanceText(route.cumulative[i]-last)+', '+(Math.abs(angle)>145?'turn back':angle>0?'turn right':'turn left')+' onto the mapped path.'});last=route.cumulative[i]}}list.push({index:route.coords.length-1,distance:route.length,text:'Continue '+distanceText(route.length-last)+(navRoute?.endpointChoices?.at(-1)?.approachName===studentsUnionRearApproach.name?' to the user-reported Students’ Union rear entrance approach. Check the entrance and local signs.':fields.to.building.value==='118457919'?' to the user-reported University Hall approach near the Library/Arts connection. Follow local signs to the entrance. Its exact door position and accessibility are unverified.':' to the nearby destination path. Confirm the building entrance in person.')});return list}
function setProgress(distance){document.querySelectorAll('#route-steps li').forEach((el,i)=>{const next=navSteps[i+1]?.distance??Infinity;el.classList.toggle('current',distance>=navSteps[i].distance&&distance<next)})}
function renderNavRoute(){if(!navRoute)return;document.querySelector('#nav-2d')?.remove();const group=make('g',{id:'nav-2d'}),points=navRoute.coords.map(project).map(p=>p.join(',')).join(' ');make('polyline',{points,class:'nav-route-halo'},group);make('polyline',{points,class:'nav-route'},group);navDot=make('circle',{cx:project(navRoute.coords[0])[0],cy:project(navRoute.coords[0])[1],r:7,fill:'#d38a25',stroke:'#fff','stroke-width':3},group);
if(threeReady){const data=featureCollection([{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:navRoute.coords}}]);if(campus3D.getSource('navigation-route'))campus3D.getSource('navigation-route').setData(data);else{add3DSource('navigation-route',data.features);campus3D.addLayer({id:'nav-halo',type:'line',source:'navigation-route',paint:{'line-color':'#fff','line-width':9},layout:{'line-cap':'round','line-join':'round'}});campus3D.addLayer({id:'nav-line',type:'line',source:'navigation-route',paint:{'line-color':'#258450','line-width':5},layout:{'line-cap':'round','line-join':'round'}})}navMarker?.remove();const dot=document.createElement('div');dot.className='route-dot';dot.setAttribute('aria-label','Route starting point');navMarker=new maplibregl.Marker({element:dot}).setLngLat(navRoute.coords[0]).addTo(campus3D)}}
function fitRoute2D(){if(!navRoute)return;const p=navRoute.coords.map(project),xs=p.map(p=>p[0]),ys=p.map(p=>p[1]);let w=Math.max(350,Math.max(...xs)-Math.min(...xs)+180),h=Math.max(350,Math.max(...ys)-Math.min(...ys)+180),ratio=svg.clientWidth/svg.clientHeight;if(w/h>ratio)h=w/ratio;else w=h*ratio;box={x:(Math.min(...xs)+Math.max(...xs)-w)/2,y:(Math.min(...ys)+Math.max(...ys)-h)/2,w,h};setBox()}
function positionOnRoute(distance){let i=1;while(i<navRoute.cumulative.length-1&&navRoute.cumulative[i]<distance)i++;const a=navRoute.coords[i-1],b=navRoute.coords[i],span=navRoute.cumulative[i]-navRoute.cumulative[i-1],t=Math.max(0,Math.min(1,(distance-navRoute.cumulative[i-1])/(span||1)));return {point:[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t],bearing:CampusRouting.bearing(a,b)}}
function moveNavDot(point,live=false){navMarker?.setLngLat(point);if(navMarker){navMarker.getElement().classList.toggle('live',live);navMarker.getElement().setAttribute('aria-label',live?'Device GPS position':'Route starting point')}if(navDot){const p=project(point);navDot.setAttribute('cx',p[0]);navDot.setAttribute('cy',p[1]);navDot.setAttribute('fill',live?'#377cc4':'#d38a25')}}
function showSteps(){if(!navRoute)return;stopAnimation();stopLive();set3D(false);fitRoute2D();moveNavDot(navRoute.coords[0]);setProgress(0);document.querySelector('#navigation-mode').textContent='2D OUTDOOR DIRECTIONS';navStatus.textContent='Follow the mapped path and check local signs. Use GPS for location-based progress.'}
function startLive(){if(!navRoute)return;if(!navigator.geolocation){navStatus.textContent='GPS unavailable. Use the numbered 2D steps.';return}stopAnimation();stopLive();set3D(false);fitRoute2D();document.querySelector('#navigation-mode').textContent='LIVE GPS · OUTDOOR GUIDANCE';navStatus.textContent='Waiting for your device location…';navWatch=navigator.geolocation.watchPosition(pos=>{if(!navRoute)return;const p=[pos.coords.longitude,pos.coords.latitude],accuracy=pos.coords.accuracy;if(accuracy>50){navStatus.textContent='GPS accuracy is ±'+Math.round(accuracy)+' m. Move outdoors; progress is paused.';return}let nearest=0,d=Infinity;navRoute.coords.forEach((q,i)=>{const gap=CampusRouting.distance(p,q);if(gap<d){d=gap;nearest=i}});moveNavDot(p,true);navGPS={point:p,accuracy,time:Date.now()};if(d>40){navStatus.textContent='You are away from the mapped route. Stop and check the map or plan again from your current location.';return}setProgress(navRoute.cumulative[nearest]);const remaining=Math.max(0,navRoute.length-navRoute.cumulative[nearest]);navStatus.textContent=(remaining<12?'Near the destination path. Confirm the entrance in person.':distanceText(remaining)+' along the mapped route remaining.')+' GPS accuracy ±'+Math.round(accuracy)+' m.';const c=project(p),w=420,h=w*svg.clientHeight/svg.clientWidth;box={x:c[0]-w/2,y:c[1]-h*.6,w,h};setBox()},err=>{stopLive();navStatus.textContent=err.code===1?'GPS permission declined. Use the numbered steps.':'GPS is unavailable. Use the numbered steps or retry.'},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
document.querySelector('#journey-form').addEventListener('submit',async event=>{event.preventDefault();const error=document.querySelector('#journey-error'),button=event.submitter;error.textContent='';if(!fields.to.building.value||(!navGPS&&!fields.from.building.value)){error.textContent='Choose a destination and either your current location or a starting building.';return}button.disabled=true;button.textContent='Finding mapped path…';try{await navReady;if(navGPS&&Date.now()-navGPS.time>120000)throw Error('Your saved location is older than two minutes. Refresh it, or choose a starting building.');const endpoints=[navGPS?{point:navGPS.point,maxSnap:40}:navEndpoint(fields.from.building.value)];const stop=selectedFood();if(stop)endpoints.push(navEndpoint(stop.building));endpoints.push(navEndpoint(fields.to.building.value));const route=CampusRouting.route(navGraph,endpoints);clearNavigation();navRoute=route;navSteps=routeStepList(route);const dest=registry.get(fields.to.building.value).name;document.querySelector('#navigation-heading').textContent='To '+dest;const reported=route.endpointChoices.filter(e=>e.reportedApproach);const approachNote=document.querySelector('#reported-approach-note');approachNote.hidden=!reported.length;approachNote.textContent='Using '+reported.map(e=>e.approachName).join(' and ')+'. Approximate mapped approach; accessibility and opening hours are unverified.';document.querySelector('#route-summary').textContent=distanceText(route.length)+' on mapped paths · approx. '+Math.max(1,Math.ceil(route.length/75))+' min'+(stop?' · via '+stop.name+' building':'');document.querySelector('#journey-text').textContent=(navGPS?'Current location':registry.get(fields.from.building.value).name)+' → '+dest;const ol=document.querySelector('#route-steps');ol.replaceChildren();for(const step of navSteps){const li=document.createElement('li');li.textContent=step.text;ol.append(li)}navPanel.hidden=false;document.body.classList.add('navigating');dialog.close();setFoodMode(false);setVendingMode(false);setParkingMode(false);paint();renderNavRoute();if(navGPS)startLive();else showSteps()}catch(e){error.textContent=e.message}finally{button.disabled=false;button.textContent='Confirm & start navigation'}});
document.querySelector('#steps-route').onclick=showSteps;document.querySelector('#live-route').onclick=startLive;document.querySelector('#close-navigation').onclick=clearNavigation;
window.addEventListener('pagehide',()=>{stopAnimation();stopLive()});

document.querySelector('#journey-form').addEventListener('input',()=>{if(navRoute)clearNavigation()});

function showReportedApproach(){if(!document.querySelector('#reported-approach-2d')){const g=make('g',{id:'reported-approach-2d'}),p=project(universityHallApproach.point);make('circle',{cx:p[0],cy:p[1],r:5,fill:'#7756a0',stroke:'#fff','stroke-width':2},g);const t=make('text',{x:p[0],y:p[1]-12,class:'label reported-entrance-label'},g);t.textContent='UH approach · reported';make('title',{},g).textContent=universityHallApproach.source}if(threeReady&&!document.querySelector('#reported-approach-3d')){const el=document.createElement('button');el.id='reported-approach-3d';el.className='model-label reported-approach-marker';el.textContent='↪ UH approach · reported';el.title=universityHallApproach.source;el.onclick=()=>openBuilding('118457919');new maplibregl.Marker({element:el}).setLngLat(universityHallApproach.point).addTo(campus3D)}}
const entranceTimer=setInterval(()=>{if(!registry.size)return;showReportedApproach();if(threeReady)clearInterval(entranceTimer)},400);
